function referralCode(){for(let i=0;i<8;i++){const c=crypto.randomBytes(5).toString('base64url').slice(0,8).toUpperCase();if(!DB.prepare('SELECT 1 FROM users WHERE referral_code=?').get(c))return c}throw new Error('Could not create referral code')}


function id(){return crypto.randomUUID()}
function hashToken(t){return crypto.createHash('sha256').update(t).digest('hex')}
function token(userId,type,minutes=60){let raw=crypto.randomBytes(32).toString('hex');DB.prepare('INSERT INTO tokens(user_id,type,token_hash,expires_at) VALUES(?,?,?,datetime("now",?))').run(userId,type,hashToken(raw),`+${minutes} minutes`);return raw}
function audit(actor,action,target,metadata={}){DB.prepare('INSERT INTO audit_logs(actor_id,action,target_id,metadata) VALUES(?,?,?,?)').run(actor||null,action,target||null,JSON.stringify(metadata))}
function auth(req,res,next){try{let t=req.cookies.habeshan;if(!t)throw 0;let p=jwt.verify(t,JWT_SECRET);let u=DB.prepare('SELECT * FROM users WHERE id=? AND disabled=0').get(p.sub);if(!u)throw 0;let session=DB.prepare('SELECT * FROM sessions WHERE id=? AND user_id=? AND revoked_at IS NULL').get(p.sid,p.sub);if(!session)throw 0;let last=new Date(String(session.last_seen).replace(' ','T')+'Z').getTime();if(Number.isFinite(last)&&Date.now()-last>SESSION_MAX_DAYS*864e5){DB.prepare('UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?').run(session.id);throw 0}DB.prepare('UPDATE sessions SET last_seen=CURRENT_TIMESTAMP WHERE id=?').run(session.id);req.session=session;req.user=u;next()}catch{res.status(401).json({error:'Authentication required'})}}
function admin(req,res,next){
  const configured=(process.env.ADMIN_EMAIL||'').toLowerCase();
  if(!req.user || (req.user.role!=='admin' && req.user.email.toLowerCase()!==configured))
    return res.status(403).json({error:'Admin access required'});
  next();
}
function setAuth(res,user){let session=id();let jwtv=jwt.sign({sub:user.id,sid:session},JWT_SECRET,{expiresIn:'30d'});DB.prepare('INSERT INTO sessions(id,user_id,user_agent,ip) VALUES(?,?,?,?)').run(session,user.id,'web','unknown');res.cookie('habeshan',jwtv,{httpOnly:true,sameSite:'lax',secure:process.env.NODE_ENV==='production',domain:process.env.COOKIE_DOMAIN||undefined,maxAge:SESSION_MAX_DAYS*864e5})}
function publicUser(u){if(!u.referral_code){try{const c=referralCode();DB.prepare('UPDATE users SET referral_code=? WHERE id=?').run(c,u.id);u.referral_code=c}catch{}} const photos=DB.prepare('SELECT id,path FROM profile_photos WHERE user_id=? ORDER BY sort_order,id').all(u.id); if(!photos.length && u.photo_path) photos.push({id:null,path:u.photo_path}); const last=DB.prepare('SELECT MAX(last_seen) last_seen FROM sessions WHERE user_id=? AND revoked_at IS NULL').get(u.id)?.last_seen||null; const online=!!last && (Date.now()-new Date(last.replace(' ','T')+'Z').getTime()<5*60*1000); return {id:u.id,name:u.name,age:u.age,city:u.city,bio:u.bio,gender:u.gender,interestedIn:u.interested_in,verified:!!u.verified,photoPath:u.photo_path||'',photos,online,lastSeen:last,languages:u.languages||'',education:u.education||'',occupation:u.occupation||'',interests:u.interests||''}}
async function sendEmail(to,subject,text){if(process.env.EMAIL_PROVIDER==='console'||!process.env.EMAIL_PROVIDER){console.log('\\n[DEV EMAIL]',{to,subject,text});return {ok:true}};throw new Error('Email provider adapter is not installed. Configure a production adapter.')}
function premiumActive(userId){const row=DB.prepare("SELECT * FROM subscriptions WHERE user_id=? AND status='active' ORDER BY id DESC LIMIT 1").get(userId);if(!row)return false;if(row.expires_at && new Date(row.expires_at.replace(' ','T')+'Z').getTime()<Date.now()){DB.prepare("UPDATE subscriptions SET status='expired' WHERE id=?").run(row.id);return false}return true}
function boostActive(userId){const row=DB.prepare("SELECT * FROM boosts WHERE user_id=? AND status='active' AND expires_at>datetime('now') ORDER BY id DESC LIMIT 1").get(userId);return row||null}
function premiumSummary(userId){const active=premiumActive(userId);const boost=boostActive(userId);return {active,plan:active?(DB.prepare("SELECT plan FROM subscriptions WHERE user_id=? AND status='active' ORDER BY id DESC LIMIT 1").get(userId)?.plan||'premium_monthly'):null,boostActive:!!boost,boostExpiresAt:boost?.expires_at||null,superLikesRemaining:Math.max(0,(active?5:1)-DB.prepare("SELECT COUNT(*) c FROM super_likes WHERE user_id=? AND created_at>=datetime('now','start of month')").get(userId).c)} }
function mutual(a,b){return !!DB.prepare('SELECT 1 FROM likes WHERE from_id=? AND to_id=?').get(a,b)&&!!DB.prepare('SELECT 1 FROM likes WHERE from_id=? AND to_id=?').get(b,a)}

app.post('/api/auth/register',async(req,res)=>{
 try{let {email,password,name,age,city='',bio='',gender='',interestedIn='',termsAccepted,referralCode:refCode}=req.body||{};
  email=String(email||'').trim().toLowerCase();name=String(name||'').trim();age=Number(age);
  if(!email||!password||!name||age<18||!termsAccepted)return res.status(400).json({error:'Email, password, name, age 18+, and terms acceptance are required'});
  if(password.length<8)return res.status(400).json({error:'Password must be at least 8 characters'});
  if(DB.prepare('SELECT 1 FROM users WHERE email=?').get(email))return res.status(409).json({error:'Email already registered'});
  let uid=id();let referrer=refCode?DB.prepare('SELECT id FROM users WHERE referral_code=? AND disabled=0').get(String(refCode).trim().toUpperCase()):null;DB.prepare('INSERT INTO users(id,email,password_hash,name,age,city,bio,gender,interested_in,role,referral_code,referred_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)').run(uid,email,await bcrypt.hash(password,12),name,age,city,bio,gender,interestedIn,'user',referralCode(),referrer?.id||null);if(referrer&&referrer.id!==uid)DB.prepare('INSERT INTO referrals(referrer_id,referred_id,code,status) VALUES(?,?,?,?)').run(referrer.id,uid,String(refCode).trim().toUpperCase(),'pending');
  let raw=token(uid,'verify',1440);await sendEmail(email,'Verify your Habeshan Dating account',`${process.env.BASE_URL||'http://localhost:3000'}/api/auth/verify?token=${raw}`);
  let u=DB.prepare('SELECT * FROM users WHERE id=?').get(uid);setAuth(res,u);audit(uid,'register',uid);res.json({user:publicUser(u),message:'Account created. Check your email to verify it.'});
 }catch(e){res.status(500).json({error:e.message})}
});
app.get('/api/auth/verify',(req,res)=>{let row=DB.prepare('SELECT * FROM tokens WHERE token_hash=? AND type="verify" AND used_at IS NULL AND expires_at>datetime("now")').get(hashToken(String(req.query.token||'')));if(!row)return res.status(400).send('Invalid or expired verification link.');DB.prepare('UPDATE users SET verified=1 WHERE id=?').run(row.user_id);DB.prepare('UPDATE tokens SET used_at=datetime("now") WHERE id=?').run(row.id);const referral=DB.prepare('SELECT * FROM referrals WHERE referred_id=? AND status="pending"').get(row.user_id);if(referral){DB.prepare('UPDATE referrals SET status="completed",rewarded_at=datetime("now") WHERE id=?').run(referral.id);DB.prepare('INSERT INTO boosts(user_id,status,started_at,expires_at,provider) VALUES(?,"active",datetime("now"),datetime("now","+30 minutes"),"referral")').run(referral.referrer_id);DB.prepare('INSERT INTO notifications(user_id,type,message) VALUES(?,?,?)').run(referral.referrer_id,'referral_reward','A friend joined Habeshan Dating from your invite. You earned a 30-minute profile boost!');io.to('user:'+referral.referrer_id).emit('notification',{type:'referral_reward'});}res.send('Email verified. You can return to Habeshan Dating.')});
app.post('/api/auth/login',async(req,res)=>{let {email,password}=req.body||{};let u=DB.prepare('SELECT * FROM users WHERE email=?').get(String(email||'').trim().toLowerCase());if(!u||u.disabled||!(await bcrypt.compare(password||'',u.password_hash)))return res.status(401).json({error:'Invalid email or password'});setAuth(res,u);audit(u.id,'login',u.id);res.json({user:publicUser(u)})});
app.post('/api/auth/logout',auth,(req,res)=>{DB.prepare('UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE id=?').run(req.session.id);res.clearCookie('habeshan',{domain:process.env.COOKIE_DOMAIN||undefined});res.json({ok:true})});
app.post('/api/auth/change-password',auth,async(req,res)=>{
  const {currentPassword,newPassword}=req.body||{};
  if(!currentPassword||!newPassword||String(newPassword).length<8)return res.status(400).json({error:'Current password and a new password of at least 8 characters are required'});
  if(!(await bcrypt.compare(currentPassword,req.user.password_hash)))return res.status(400).json({error:'Current password is incorrect'});
  DB.prepare('UPDATE users SET password_hash=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(await bcrypt.hash(newPassword,12),req.user.id);
  DB.prepare('UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=?').run(req.user.id);
  audit(req.user.id,'change_password',req.user.id);
  res.clearCookie('habeshan'); res.json({ok:true,message:'Password changed. Please sign in again.'});
});
app.post('/api/auth/logout-all',auth,(req,res)=>{
  DB.prepare('UPDATE sessions SET revoked_at=CURRENT_TIMESTAMP WHERE user_id=?').run(req.user.id);
  res.clearCookie('habeshan'); audit(req.user.id,'logout_all',req.user.id); res.json({ok:true});
});
