const upload=multer({storage:multer.diskStorage({destination:uploadDir,filename:(req,f,cb)=>cb(null,crypto.randomUUID()+path.extname(f.originalname).toLowerCase())}),limits:{fileSize:Number(process.env.MAX_UPLOAD_MB||8)*1024*1024},fileFilter:(req,f,cb)=>cb(/image\/(jpeg|png|webp)/.test(f.mimetype)?null:new Error('Only JPG, PNG or WebP images are allowed'))});
app.post('/api/profile/photo',auth,upload.single('photo'),(req,res)=>{if(!req.file)return res.status(400).json({error:'Photo required'});const photo='/uploads/'+req.file.filename;const count=DB.prepare('SELECT COUNT(*) c FROM profile_photos WHERE user_id=?').get(req.user.id).c;DB.prepare('INSERT INTO profile_photos(user_id,path,sort_order) VALUES(?,?,?)').run(req.user.id,photo,count);if(!req.user.photo_path)DB.prepare('UPDATE users SET photo_path=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(photo,req.user.id);audit(req.user.id,'upload_photo',req.user.id,{file:req.file.filename});res.json({ok:true,path:photo})});
app.post('/api/profile/photos',auth,upload.array('photos',6),(req,res)=>{if(!req.files?.length)return res.status(400).json({error:'Choose at least one photo'});let next=DB.prepare('SELECT COUNT(*) c FROM profile_photos WHERE user_id=?').get(req.user.id).c;const paths=[];for(const f of req.files){const photo='/uploads/'+f.filename;DB.prepare('INSERT INTO profile_photos(user_id,path,sort_order) VALUES(?,?,?)').run(req.user.id,photo,next++);paths.push(photo)}if(!req.user.photo_path)DB.prepare('UPDATE users SET photo_path=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(paths[0],req.user.id);audit(req.user.id,'upload_photo_gallery',req.user.id,{count:paths.length});res.json({ok:true,paths})});
app.delete('/api/profile/photos/:id',auth,(req,res)=>{const row=DB.prepare('SELECT * FROM profile_photos WHERE id=? AND user_id=?').get(req.params.id,req.user.id);if(!row)return res.status(404).json({error:'Photo not found'});try{fs.unlinkSync(path.join(__dirname,row.path.replace(/^\//,'')))}catch{}DB.prepare('DELETE FROM profile_photos WHERE id=?').run(row.id);const first=DB.prepare('SELECT path FROM profile_photos WHERE user_id=? ORDER BY sort_order,id LIMIT 1').get(req.user.id);DB.prepare('UPDATE users SET photo_path=?,updated_at=CURRENT_TIMESTAMP WHERE id=?').run(first?.path||'',req.user.id);res.json({ok:true})});
app.post('/api/profile/photos/reorder',auth,(req,res)=>{const ids=Array.isArray(req.body?.ids)?req.body.ids.map(Number):[];const owned=DB.prepare(`SELECT id FROM profile_photos WHERE user_id=?`).all(req.user.id).map(x=>x.id);if(ids.some(x=>!owned.includes(x))||new Set(ids).size!==ids.length)return res.status(400).json({error:'Invalid photo order'});const stmt=DB.prepare('UPDATE profile_photos SET sort_order=? WHERE id=? AND user_id=?');const tx=DB.transaction(()=>ids.forEach((pid,i)=>stmt.run(i,pid,req.user.id)));tx();const first=DB.prepare('SELECT path FROM profile_photos WHERE user_id=? ORDER BY sort_order,id LIMIT 1').get(req.user.id);DB.prepare('UPDATE users SET photo_path=? WHERE id=?').run(first?.path||'',req.user.id);res.json({ok:true})});
app.delete('/api/profile/photo',auth,(req,res)=>{const rows=DB.prepare('SELECT id FROM profile_photos WHERE user_id=?').all(req.user.id);for(const r of rows){const row=DB.prepare('SELECT path FROM profile_photos WHERE id=?').get(r.id);try{fs.unlinkSync(path.join(__dirname,row.path.replace(/^\//,'')))}catch{}}DB.prepare('DELETE FROM profile_photos WHERE user_id=?').run(req.user.id);DB.prepare('UPDATE users SET photo_path="" WHERE id=?').run(req.user.id);audit(req.user.id,'delete_photo',req.user.id);res.json({ok:true})});
