app.get('/api/discover',auth,(req,res)=>{let {city='',minAge=18,maxAge=80,gender=''}=req.query;let sql=`SELECT * FROM users WHERE id<>? AND disabled=0 AND age BETWEEN ? AND ? AND id NOT IN (SELECT to_id FROM passes WHERE from_id=?) AND id NOT IN (SELECT to_id FROM likes WHERE from_id=?) AND id NOT IN (SELECT to_id FROM blocks WHERE from_id=?) AND id NOT IN (SELECT from_id FROM blocks WHERE to_id=?)`;let p=[req.user.id,Number(minAge)||18,Number(maxAge)||80,req.user.id,req.user.id,req.user.id,req.user.id];if(city){sql+=' AND city LIKE ?';p.push('%'+city+'%')}if(gender){sql+=' AND gender=?';p.push(gender)}sql+=` ORDER BY ${boostActive(req.user.id)?"CASE WHEN id IN (SELECT user_id FROM boosts WHERE status='active' AND expires_at>datetime('now')) THEN 0 ELSE 1 END,":''} created_at DESC LIMIT 50`;res.json({users:DB.prepare(sql).all(...p).map(publicUser)})});
app.post('/api/like/:id',auth,(req,res)=>{let target=DB.prepare('SELECT * FROM users WHERE id=? AND disabled=0').get(req.params.id);if(!target)return res.status(404).json({error:'User not found'});DB.prepare('INSERT OR IGNORE INTO likes(from_id,to_id) VALUES(?,?)').run(req.user.id,target.id);let match=mutual(req.user.id,target.id);if(match){DB.prepare('INSERT INTO notifications(user_id,type,message) VALUES(?,?,?)').run(target.id,'match',`You matched with ${req.user.name}`);DB.prepare('INSERT INTO notifications(user_id,type,message) VALUES(?,?,?)').run(req.user.id,'match',`You matched with ${target.name}`);io.to('user:'+target.id).emit('notification',{type:'match'});audit(req.user.id,'match',target.id)}else audit(req.user.id,'like',target.id);res.json({ok:true,match})});

