app.post('/api/billing/checkout',auth,async(req,res)=>{try{let plan=String(req.body?.plan||'premium_monthly');if(!['premium_monthly','premium_yearly'].includes(plan))return res.status(400).json({error:'Invalid plan'});const real=!!process.env.STRIPE_SECRET_KEY&&!!process.env.STRIPE_PRICE_MONTHLY&&!!process.env.STRIPE_PRICE_YEARLY; if(real){const price=plan==='premium_yearly'?process.env.STRIPE_PRICE_YEARLY:process.env.STRIPE_PRICE_MONTHLY;const base=(process.env.BASE_URL||`http://localhost:${PORT}`).replace(/\/$/,'');const params=new URLSearchParams();params.set('mode','subscription');params.set('line_items[0][price]',price);params.set('line_items[0][quantity]','1');params.set('success_url',`${base}/?payment=success&session_id={CHECKOUT_SESSION_ID}`);params.set('cancel_url',`${base}/?payment=cancelled`);params.set('customer_email',req.user.email);params.set('metadata[userId]',req.user.id);params.set('metadata[plan]',plan);params.set('subscription_data[metadata][userId]',req.user.id);params.set('subscription_data[metadata][plan]',plan);const r=await fetch('https://api.stripe.com/v1/checkout/sessions',{method:'POST',headers:{Authorization:`Bearer ${process.env.STRIPE_SECRET_KEY}`,'Content-Type':'application/x-www-form-urlencoded'},body:params});const data=await r.json();if(!r.ok)return res.status(502).json({error:data.error?.message||'Payment provider error'});DB.prepare("INSERT INTO subscriptions(user_id,plan,status,provider,provider_ref) VALUES(?,?,?,?,?)").run(req.user.id,plan,'pending','stripe',data.id);audit(req.user.id,'checkout_started',req.user.id,{plan,provider:'stripe'});return res.json({ok:true,provider:'stripe',checkoutUrl:data.url,sessionId:data.id});}const days=plan==='premium_yearly'?365:30;DB.prepare("UPDATE subscriptions SET status='expired' WHERE user_id=? AND status='active'").run(req.user.id);DB.prepare("INSERT INTO subscriptions(user_id,plan,status,provider,provider_ref,expires_at) VALUES(?,?,?,?,?,datetime('now',?))").run(req.user.id,plan,'active','demo','demo-'+id(),`+${days} days`);audit(req.user.id,'demo_upgrade',req.user.id,{plan});res.json({ok:true,demo:true,message:`Demo ${plan.replace('_',' ')} activated. No payment was charged.`,premium:premiumSummary(req.user.id)});}catch(e){res.status(500).json({error:'Checkout could not be started.'})}});
