io.on('connection',(socket)=>{let cookie=socket.handshake.headers.cookie||'';let m=cookie.match(/(?:^|; )habeshan=([^;]+)/);if(!m)return;try{let p=jwt.verify(decodeURIComponent(m[1]),JWT_SECRET);socket.join('user:'+p.sub);DB.prepare('UPDATE sessions SET last_seen=CURRENT_TIMESTAMP WHERE user_id=? AND revoked_at IS NULL').run(p.sub);io.emit('presence',{userId:p.sub,online:true});socket.on('typing',d=>{if(d?.to && mutual(p.sub,d.to))io.to('user:'+d.to).emit('typing',{from:p.sub})});socket.on('read',d=>{if(d?.to && mutual(p.sub,d.to))io.to('user:'+d.to).emit('read',{by:p.sub})});socket.on('disconnect',()=>{DB.prepare('UPDATE sessions SET last_seen=CURRENT_TIMESTAMP WHERE user_id=? AND revoked_at IS NULL').run(p.sub);io.emit('presence',{userId:p.sub,online:false,lastSeen:new Date().toISOString()})})}catch{}});

// V8 operational endpoints

DB.exec(`
CREATE TABLE IF NOT EXISTS community_posts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,body TEXT NOT NULL,photo_path TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS community_likes(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(post_id,user_id));
CREATE TABLE IF NOT EXISTS community_comments(id INTEGER PRIMARY KEY AUTOINCREMENT,post_id INTEGER NOT NULL,user_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS follows(id INTEGER PRIMARY KEY AUTOINCREMENT,follower_id TEXT NOT NULL,following_id TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(follower_id,following_id));
CREATE INDEX IF NOT EXISTS idx_posts_created ON community_posts(created_at);
`);
function communityPost(row, viewerId){const u=DB.prepare('SELECT id,name,photo_path,verified FROM users WHERE id=?').get(row.user_id)||{};const likes=DB.prepare('SELECT COUNT(*) c FROM community_likes WHERE post_id=?').get(row.id).c;const liked=!!DB.prepare('SELECT 1 FROM community_likes WHERE post_id=? AND user_id=?').get(row.id,viewerId);const comments=DB.prepare('SELECT c.id,c.body,c.created_at,u.name,u.photo_path,u.verified FROM community_comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.id ASC LIMIT 30').all(row.id);return {...row,author:{id:u.id,name:u.name,photoPath:u.photo_path||'',verified:!!u.verified},likes,liked,comments}}
app.get('/api/community/feed',auth,(req,res)=>{const limit=Math.min(50,Math.max(1,Number(req.query.limit)||20));const rows=DB.prepare('SELECT * FROM community_posts ORDER BY id DESC LIMIT ?').all(limit);res.json({posts:rows.map(r=>communityPost(r,req.user.id))})});
app.post('/api/community/posts',auth,(req,res)=>{const body=String(req.body?.body||'').trim();if(!body||body.length>1000)return res.status(400).json({error:'Post must contain 1–1000 characters'});const info=DB.prepare('INSERT INTO community_posts(user_id,body) VALUES(?,?)').run(req.user.id,body);res.status(201).json({post:communityPost(DB.prepare('SELECT * FROM community_posts WHERE id=?').get(info.lastInsertRowid),req.user.id)})});
app.delete('/api/community/posts/:id',auth,(req,res)=>{const row=DB.prepare('SELECT * FROM community_posts WHERE id=?').get(req.params.id);if(!row)return res.status(404).json({error:'Post not found'});if(row.user_id!==req.user.id&&req.user.role!=='admin')return res.status(403).json({error:'Not allowed'});DB.prepare('DELETE FROM community_comments WHERE post_id=?').run(row.id);DB.prepare('DELETE FROM community_likes WHERE post_id=?').run(row.id);DB.prepare('DELETE FROM community_posts WHERE id=?').run(row.id);res.json({ok:true})});
app.post('/api/community/posts/:id/like',auth,(req,res)=>{const id=Number(req.params.id);if(!DB.prepare('SELECT 1 FROM community_posts WHERE id=?').get(id))return res.status(404).json({error:'Post not found'});const exists=DB.prepare('SELECT 1 FROM community_likes WHERE post_id=? AND user_id=?').get(id,req.user.id);if(exists)DB.prepare('DELETE FROM community_likes WHERE post_id=? AND user_id=?').run(id,req.user.id);else DB.prepare('INSERT INTO community_likes(post_id,user_id) VALUES(?,?)').run(id,req.user.id);res.json({liked:!exists,likes:DB.prepare('SELECT COUNT(*) c FROM community_likes WHERE post_id=?').get(id).c})});
app.post('/api/community/posts/:id/comments',auth,(req,res)=>{const id=Number(req.params.id),body=String(req.body?.body||'').trim();if(!body||body.length>500)return res.status(400).json({error:'Comment must contain 1–500 characters'});if(!DB.prepare('SELECT 1 FROM community_posts WHERE id=?').get(id))return res.status(404).json({error:'Post not found'});const info=DB.prepare('INSERT INTO community_comments(post_id,user_id,body) VALUES(?,?,?)').run(id,req.user.id,body);const c=DB.prepare('SELECT c.*,u.name,u.photo_path,u.verified FROM community_comments c JOIN users u ON u.id=c.user_id WHERE c.id=?').get(info.lastInsertRowid);res.status(201).json({comment:c})});
app.post('/api/community/follow/:id',auth,(req,res)=>{const target=String(req.params.id);if(target===req.user.id)return res.status(400).json({error:'You cannot follow yourself'});if(!DB.prepare('SELECT 1 FROM users WHERE id=? AND disabled=0').get(target))return res.status(404).json({error:'User not found'});const exists=DB.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(req.user.id,target);if(exists)DB.prepare('DELETE FROM follows WHERE follower_id=? AND following_id=?').run(req.user.id,target);else DB.prepare('INSERT INTO follows(follower_id,following_id) VALUES(?,?)').run(req.user.id,target);res.json({following:!exists})});
app.get('/api/community/profile/:id',auth,(req,res)=>{const id=String(req.params.id);const u=DB.prepare('SELECT id,name,age,city,bio,photo_path,verified,interests FROM users WHERE id=? AND disabled=0').get(id);if(!u)return res.status(404).json({error:'User not found'});res.json({user:u,following:!!DB.prepare('SELECT 1 FROM follows WHERE follower_id=? AND following_id=?').get(req.user.id,id),followers:DB.prepare('SELECT COUNT(*) c FROM follows WHERE following_id=?').get(id).c,followingCount:DB.prepare('SELECT COUNT(*) c FROM follows WHERE follower_id=?').get(id).c})});
