DB.exec(`CREATE TABLE IF NOT EXISTS discovery_preferences(user_id TEXT PRIMARY KEY,min_age INTEGER DEFAULT 18,max_age INTEGER DEFAULT 80,city TEXT DEFAULT '',gender TEXT DEFAULT '',interests TEXT DEFAULT '',distance_label TEXT DEFAULT 'Any',relationship_goal TEXT DEFAULT '',distance_km INTEGER DEFAULT 100,deal_breakers_json TEXT DEFAULT '[]',countries TEXT DEFAULT '',cities TEXT DEFAULT '',languages TEXT DEFAULT '',diaspora_only INTEGER DEFAULT 0,verified_only INTEGER DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
function preferenceRow(uid){return DB.prepare('SELECT * FROM discovery_preferences WHERE user_id=?').get(uid)||{user_id:uid,min_age:18,max_age:80,city:'',gender:'',interests:'',distance_label:'Any'}}
app.get('/api/discovery/preferences',auth,(req,res)=>res.json({preferences:preferenceRow(req.user.id)}));
app.put('/api/discovery/preferences',auth,(req,res)=>{const b=req.body||{};const min=Math.max(18,Math.min(80,Number(b.minAge)||18)),max=Math.max(min,Math.min(100,Number(b.maxAge)||80));const city=String(b.city||'').trim().slice(0,80),gender=String(b.gender||'').trim().slice(0,30),interests=String(b.interests||'').trim().slice(0,300);DB.prepare(`INSERT INTO discovery_preferences(user_id,min_age,max_age,city,gender,interests,distance_label) VALUES(?,?,?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET min_age=excluded.min_age,max_age=excluded.max_age,city=excluded.city,gender=excluded.gender,interests=excluded.interests,distance_label=excluded.distance_label`).run(req.user.id,min,max,city,gender,interests,String(b.distanceLabel||'Any'));res.json({preferences:preferenceRow(req.user.id)})});
app.get('/api/discover/recommended',auth,(req,res)=>{const p=preferenceRow(req.user.id);let sql=`SELECT * FROM users WHERE id<>? AND disabled=0 AND age BETWEEN ? AND ? AND id NOT IN (SELECT to_id FROM passes WHERE from_id=?) AND id NOT IN (SELECT to_id FROM likes WHERE from_id=?) AND id NOT IN (SELECT to_id FROM blocks WHERE from_id=?) AND id NOT IN (SELECT from_id FROM blocks WHERE to_id=?)`;let args=[req.user.id,p.min_age,p.max_age,req.user.id,req.user.id,req.user.id,req.user.id];if(p.city){sql+=' AND city LIKE ?';args.push('%'+p.city+'%')}if(p.gender){sql+=' AND gender=?';args.push(p.gender)}const users=DB.prepare(sql).all(...args).map(u=>{const interests=(u.interests||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean), wanted=(p.interests||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean);let score=0;if(p.city&&u.city?.toLowerCase().includes(p.city.toLowerCase()))score+=30;if(p.gender&&u.gender===p.gender)score+=20;score+=wanted.filter(x=>interests.includes(x)).length*10;if(u.verified)score+=5;const boost=boostActive(u.id);if(boost)score+=8;return {...publicUser(u),matchScore:Math.min(99,score),matchReasons:[p.city&&u.city?.toLowerCase().includes(p.city.toLowerCase())?'Same city':null,p.gender&&u.gender===p.gender?'Preferred gender':null,wanted.filter(x=>interests.includes(x)).length? 'Shared interests':null,u.verified?'Verified profile':null].filter(Boolean)} }).sort((a,b)=>b.matchScore-a.matchScore);res.json({users:users.slice(0,30),preferences:p})});
