function growthEvent(userId,event,metadata={}){DB.prepare('INSERT INTO growth_events(user_id,event,metadata) VALUES(?,?,?)').run(userId,event,JSON.stringify(metadata).slice(0,2000));}
function ensureGrowthPrefs(userId){DB.prepare('INSERT OR IGNORE INTO onboarding(user_id) VALUES(?)').run(userId);DB.prepare('INSERT OR IGNORE INTO notification_preferences(user_id) VALUES(?)').run(userId);}
function today(){return new Date().toISOString().slice(0,10)}
function activityStreak(userId){const rows=DB.prepare('SELECT day FROM activity_days WHERE user_id=? ORDER BY day DESC LIMIT 90').all(userId).map(x=>x.day);let streak=0, d=new Date();for(let i=0;i<rows.length;i++){const want=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()-i)).toISOString().slice(0,10);if(rows[i]!==want)break;streak++}return streak}
