app.get('/api/v28/preferences',auth,(req,res)=>{let p=DB.prepare('SELECT * FROM compatibility_preferences WHERE user_id=?').get(req.user.id);if(!p){p={user_id:req.user.id,min_age:18,max_age:80,city:'',languages:'',education:'',interests:''}}res.json({preferences:p})});
app.put('/api/v28/preferences',auth,(req,res)=>{let p={min_age:Math.max(18,Number(req.body?.minAge)||18),max_age:Math.min(100,Number(req.body?.maxAge)||80),city:String(req.body?.city||'').slice(0,80),languages:String(req.body?.languages||'').slice(0,200),education:String(req.body?.education||'').slice(0,120),interests:String(req.body?.interests||'').slice(0,500)};DB.prepare(`INSERT INTO compatibility_preferences(user_id,min_age,max_age,city,languages,education,interests,updated_at) VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(user_id) DO UPDATE SET min_age=excluded.min_age,max_age=excluded.max_age,city=excluded.city,languages=excluded.languages,education=excluded.education,interests=excluded.interests,updated_at=CURRENT_TIMESTAMP`).run(req.user.id,p.min_age,p.max_age,p.city,p.languages,p.education,p.interests);res.json({ok:true,preferences:p})});
app.get('/api/v28/compatibility/:id',auth,(req,res)=>{const u=DB.prepare('SELECT * FROM users WHERE id=? AND disabled=0').get(req.params.id);if(!u)return res.status(404).json({error:'Profile not found'});const me=DB.prepare('SELECT * FROM users WHERE id=?').get(req.user.id);const interests=(x)=>new Set(String(x||'').split(/[,|]/).map(s=>s.trim().toLowerCase()).filter(Boolean));const a=interests(me.interests),b=interests(u.interests);const shared=[...a].filter(x=>b.has(x));let score=20+Math.min(35,shared.length*7);if(me.city&&u.city&&me.city.toLowerCase()===u.city.toLowerCase())score+=15;if(me.education&&u.education&&me.education.toLowerCase()===u.education.toLowerCase())score+=10;if(me.languages&&u.languages){const la=interests(me.languages),lb=interests(u.languages);if([...la].some(x=>lb.has(x)))score+=10}if(me.interested_in&&u.gender&&me.interested_in.toLowerCase().includes(u.gender.toLowerCase()))score+=5;score=Math.min(100,score);const reasons=[];if(shared.length)reasons.push(`${shared.length} shared interest${shared.length>1?'s':''}`);if(me.city&&u.city&&me.city.toLowerCase()===u.city.toLowerCase())reasons.push('same city');if(me.languages&&u.languages)reasons.push('language overlap may be possible');res.json({score,reasons,sharedInterests:shared.slice(0,8)})});
