function verifyStripeSignature(raw,header,secret){if(!raw||!header||!secret)return false;const parts=Object.fromEntries(header.split(',').map(x=>x.split('=')));if(!parts.t||!parts.v1)return false;const age=Math.abs(Date.now()/1000-Number(parts.t));if(!Number.isFinite(age)||age>300)return false;const expected=crypto.createHmac('sha256',secret).update(`${parts.t}.${raw.toString()}`).digest('hex');return crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(parts.v1));}
app.post('/api/billing/webhook',(req,res)=>{try{if(!process.env.STRIPE_WEBHOOK_SECRET)return res.status(503).json({error:'Webhook secret is not configured'});const sig=req.headers['stripe-signature'];if(!verifyStripeSignature(req.rawBody,sig,process.env.STRIPE_WEBHOOK_SECRET))return res.status(400).json({error:'Invalid webhook signature'});const event=JSON.parse(req.rawBody.toString());const obj=event.data?.object||{};if(event.type==='checkout.session.completed'){const userId=obj.metadata?.userId;const plan=obj.metadata?.plan;if(userId&&plan){const days=plan==='premium_yearly'?365:30;DB.prepare("UPDATE subscriptions SET status='expired' WHERE user_id=? AND status='active'").run(userId);const pending=DB.prepare("SELECT id FROM subscriptions WHERE user_id=? AND provider='stripe' AND provider_ref=? ORDER BY id DESC LIMIT 1").get(userId,obj.id);if(pending){DB.prepare("UPDATE subscriptions SET status='active',provider_ref=?,expires_at=datetime('now',?) WHERE id=?").run(obj.subscription||obj.id,`+${days} days`,pending.id);}else{DB.prepare("INSERT INTO subscriptions(user_id,plan,status,provider,provider_ref,expires_at) VALUES(?,?,?,?,?,datetime('now',?))").run(userId,plan,'active','stripe',obj.subscription||obj.id,`+${days} days`);}audit(userId,'payment_completed',userId,{plan,provider:'stripe'});}}else if(event.type==='customer.subscription.deleted'){const sub=obj.id;DB.prepare("UPDATE subscriptions SET status='cancelled' WHERE provider='stripe' AND provider_ref=?").run(sub);}else if(event.type==='invoice.payment_failed'){const sub=obj.subscription;if(sub)DB.prepare("UPDATE subscriptions SET status='payment_failed' WHERE provider='stripe' AND provider_ref=?").run(sub);}res.json({received:true});}catch(e){res.status(400).json({error:'Invalid webhook payload'})}});

