DB.exec(`CREATE TABLE IF NOT EXISTS email_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,event TEXT DEFAULT '',to_email TEXT DEFAULT '',subject TEXT DEFAULT '',body TEXT DEFAULT '',status TEXT DEFAULT 'queued',provider TEXT DEFAULT 'console',error TEXT DEFAULT '',sent_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,email TEXT DEFAULT '',template_slug TEXT DEFAULT '',attempts INTEGER DEFAULT 0,last_error TEXT);`);
function emailProvider(){return process.env.EMAIL_PROVIDER||'console'}
async function sendTransactionalEmail({userId,to,subject,body,event}){const provider=emailProvider();let status='queued',error='';try{if(provider==='console'){console.log('[email:console]',{to,subject,event});status='sent'}else if(provider==='resend'&&process.env.RESEND_API_KEY){const r=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${process.env.RESEND_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({from:process.env.EMAIL_FROM||'Habeshan Dating <noreply@example.com>',to:[to],subject,html:body})});if(!r.ok)throw new Error(`Resend ${r.status}`);status='sent'}else if(provider==='smtp'){status='queued'}else{throw new Error('Email provider is not configured')}}catch(e){status='failed';error=String(e.message||e)}DB.prepare('INSERT INTO email_jobs(user_id,event,to_email,subject,body,status,provider,error,sent_at) VALUES(?,?,?,?,?,?,?,?,CASE WHEN ?="sent" THEN CURRENT_TIMESTAMP ELSE NULL END)').run(userId||null,event,to,subject,body,status,provider,error,status);return {status,error}}
