DB.exec(`CREATE TABLE IF NOT EXISTS security_events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,ip TEXT,event TEXT NOT NULL,risk INTEGER DEFAULT 0,metadata TEXT DEFAULT '',created_at TEXT DEFAULT CURRENT_TIMESTAMP,user_agent TEXT DEFAULT ''); CREATE INDEX IF NOT EXISTS idx_security_events_ip ON security_events(ip,created_at);`);
function riskFor(req){let score=0;const ip=String(req.ip||'unknown');const recent=DB.prepare("SELECT COUNT(*) c FROM security_events WHERE ip=? AND created_at>=datetime('now','-15 minutes')").get(ip).c;if(recent>30)score+=60;else if(recent>10)score+=25;const ua=String(req.headers['user-agent']||'');if(!ua)score+=10;return Math.min(100,score)}
app.use((req,res,next)=>{if(req.path.startsWith('/api/')){const risk=riskFor(req);if(risk>=90)return res.status(429).json({error:'Too many suspicious requests'});if(risk>=50&&req.user?.id){DB.prepare('INSERT INTO security_events(user_id,ip,event,risk,metadata) VALUES(?,?,?,?,?)').run(req.user.id,req.ip,'high_risk_request',risk,JSON.stringify({path:req.path}))}}next()});
app.get('/api/v66/security/status',auth,admin,(req,res)=>res.json({version:'66.0.0',securityHeaders:true,rateLimit:true,riskEngine:true,recentHighRisk:DB.prepare("SELECT COUNT(*) c FROM security_events WHERE risk>=50 AND created_at>=datetime('now','-24 hours')").get().c}));
app.post('/api/v66/security/report',auth,(req,res)=>{const event=String(req.body?.event||'user_report').slice(0,80);const risk=Math.min(100,Math.max(0,Number(req.body?.risk)||0));DB.prepare('INSERT INTO security_events(user_id,ip,event,risk,metadata) VALUES(?,?,?,?,?)').run(req.user.id,req.ip,event,risk,JSON.stringify(req.body?.metadata||{}));res.json({ok:true})});
app.get('/api/v66/features',(req,res)=>res.json({version:'66.0.0',features:{riskScoring:true,securityEvents:true,rateLimiting:true,sessionRevocation:true,moderationControls:true}}));

