// V73 AI-Assisted Matching (deterministic scoring; no external AI is required)
function csvSet(v){return new Set(String(v||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean))}
function compatibilityScore(a,b){let score=0,reasons=[];const ai=csvSet(a.interests),bi=csvSet(b.interests);const shared=[...ai].filter(x=>bi.has(x));score+=Math.min(40,shared.length*8);if(shared.length)reasons.push(`Shared interests: ${shared.slice(0,4).join(', ')}`);if(a.city&&b.city&&a.city.toLowerCase()===b.city.toLowerCase()){score+=20;reasons.push('Same city')}if(a.languages&&b.languages&&[...csvSet(a.languages)].some(x=>csvSet(b.languages).has(x))){score+=15;reasons.push('Shared language')}if(a.education&&b.education&&a.education.toLowerCase()===b.education.toLowerCase()){score+=10;reasons.push('Similar education')}if(Math.abs(Number(a.age)-Number(b.age))<=5){score+=10;reasons.push('Similar age range')}if(b.verified) {score+=5;reasons.push('Verified profile')}return Math.min(100,score)}
app.get('/api/v73/matches',auth,(req,res)=>{const limit=Math.min(50,Math.max(1,Number(req.query.limit)||20));const candidates=DB.prepare("SELECT * FROM users WHERE id<>? AND disabled=0 AND id NOT IN (SELECT to_id FROM passes WHERE from_id=?) AND id NOT IN (SELECT to_id FROM blocks WHERE from_id=?) LIMIT 500").all(req.user.id,req.user.id,req.user.id);const scored=candidates.map(u=>{const score=compatibilityScore(req.user,u);DB.prepare('INSERT INTO match_scores(user_id,target_id,score,reasons) VALUES(?,?,?,?) ON CONFLICT(user_id,target_id) DO UPDATE SET score=excluded.score,reasons=excluded.reasons,created_at=CURRENT_TIMESTAMP').run(req.user.id,u.id,score,JSON.stringify([]));return {id:u.id,name:u.name,age:u.age,city:u.city,bio:u.bio,verified:!!u.verified,photo_path:u.photo_path,score,reasons:JSON.parse(DB.prepare('SELECT reasons FROM match_scores WHERE user_id=? AND target_id=?').get(req.user.id,u.id).reasons||'[]')}}).sort((a,b)=>b.score-a.score).slice(0,limit);res.json({matches:scored})});
app.post('/api/v73/feedback',auth,(req,res)=>{const target=String(req.body?.targetId||'');const signal=['positive','negative','not_interested'].includes(req.body?.signal)?req.body.signal:'positive';if(!DB.prepare('SELECT id FROM users WHERE id=? AND disabled=0').get(target))return res.status(404).json({error:'User not found'});DB.prepare('INSERT OR IGNORE INTO compatibility_feedback(user_id,target_id,signal) VALUES(?,?,?)').run(req.user.id,target,signal);res.json({ok:true})});
app.get('/api/v73/features',(req,res)=>res.json({version:'73.0.0',features:{compatibilityEngine:true,explainableMatches:true,feedbackLearning:true,noExternalAIRequired:true}}));

// V74 AI Safety & Moderation
function moderationRisk(text){const t=String(text||'').toLowerCase();const flags=['send money','gift card','crypto','password','verification code','otp','wire transfer'];let hits=flags.filter(x=>t.includes(x));return {risk:Math.min(100,hits.length*18),flags:hits}}
app.post('/api/v74/moderation/scan',auth,(req,res)=>{const text=String(req.body?.text||'').slice(0,5000);const result=moderationRisk(text);const status=result.risk>=36?'pending':'clear';const r=DB.prepare('INSERT INTO moderation_queue(user_id,target_id,type,content,risk,status) VALUES(?,?,?,?,?,?)').run(req.user.id,String(req.body?.targetId||''),String(req.body?.type||'message'),text,result.risk,status);res.json({ok:true,id:r.lastInsertRowid,...result,status})});
app.get('/api/v74/moderation/queue',auth,admin,(req,res)=>res.json({items:DB.prepare("SELECT * FROM moderation_queue WHERE status='pending' ORDER BY risk DESC,id DESC LIMIT 100").all()}));
app.patch('/api/v74/moderation/:id',auth,admin,(req,res)=>{const status=['approved','removed','pending'].includes(req.body?.status)?req.body.status:'pending';DB.prepare('UPDATE moderation_queue SET status=?,resolved_at=CASE WHEN ?<>\'pending\' THEN CURRENT_TIMESTAMP ELSE NULL END WHERE id=?').run(status,status,Number(req.params.id));adminAction(req,'moderation_resolved',req.params.id,{status});res.json({ok:true})});
app.get('/api/v74/features',(req,res)=>res.json({version:'74.0.0',features:{contentRiskScanning:true,moderationQueue:true,scamKeywordDetection:true,adminReview:true}}));

