const aiScore=(a,b)=>{const ai=(a.interests||'').toLowerCase().split(/[, ]+/).filter(Boolean),bi=(b.interests||'').toLowerCase().split(/[, ]+/).filter(Boolean);const shared=[...new Set(ai.filter(x=>bi.includes(x)))];return {score:Math.min(100,40+shared.length*12),shared};};
