// V93 AI Profile Coach
function profileCoach(u){const fields=['name','age','city','bio','gender','interested_in','languages','interests'];const missing=fields.filter(k=>!String(u?.[k]??'').trim());const bio=String(u?.bio||'').trim();const suggestions=[];if(bio.length<80)suggestions.push('Add a little more about your personality, interests, and what you hope to find.');if(!u?.photo_path)suggestions.push('Add a clear profile photo that represents you.');if(!String(u?.interests||'').trim())suggestions.push('List a few genuine interests to make conversations easier.');return {completeness:Math.round((fields.length-missing.length)/fields.length*100),missing,suggestions,provider:'local-deterministic'}}
app.get('/api/v93/profile-coach',auth,(req,res)=>res.json(profileCoach(req.user)));
app.post('/api/v93/profile-coach/rewrite',auth,(req,res)=>{const draft=String(req.body?.bio||req.user.bio||'').trim().slice(0,1200);const rewritten=draft?`${draft}${/[.!?]$/.test(draft)?'':' .'}`:'I enjoy meaningful conversations, good experiences, and meeting someone who shares my values and curiosity.';res.json({original:draft,rewritten,suggestions:['Keep it authentic','Mention 2–3 specific interests','Say what kind of connection you hope to build'],provider:'local-deterministic'})});
app.get('/api/v93/features',(req,res)=>res.json({version:'93.0.0',features:{profileCoach:true,completenessScore:true,bioRewrite:true,providerAbstraction:true}}));


// V94 Advanced Safety AI — heuristic signals only; human review remains authoritative
DB.exec(`CREATE TABLE IF NOT EXISTS safety_ai_signals(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,content_type TEXT NOT NULL,risk_level TEXT NOT NULL,signals_json TEXT DEFAULT '[]',status TEXT DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
function v94Risk(text){const s=String(text||'').toLowerCase();const signals=[];if(/send money|wire money|gift card|crypto|investment opportunity/.test(s))signals.push('financial-solicitation');if(/password|verification code|otp|login code/.test(s))signals.push('credential-request');if(/threaten|hurt you|kill you/.test(s))signals.push('threatening-language');const risk=signals.length>=2?'high':signals.length?'medium':'low';return {risk,signals}}
app.post('/api/v94/safety/scan',auth,(req,res)=>{const r=v94Risk(req.body?.text);DB.prepare('INSERT INTO safety_ai_signals(user_id,content_type,risk_level,signals_json) VALUES(?,?,?,?)').run(req.user.id,String(req.body?.contentType||'message'),r.risk,JSON.stringify(r.signals));res.json({...r,action:r.risk==='high'?'human-review':r.risk==='medium'?'caution':'allow',provider:'local-heuristic'})});
app.get('/api/v94/safety/signals',auth,admin,(req,res)=>res.json({signals:DB.prepare('SELECT * FROM safety_ai_signals ORDER BY id DESC LIMIT 100').all()}));
app.get('/api/v94/features',(req,res)=>res.json({version:'94.0.0',features:{safetyHeuristics:true,humanReviewHooks:true,financialScamSignals:true,credentialSignals:true,threatSignals:true}}));


