DB.exec(`CREATE TABLE IF NOT EXISTS creator_profiles(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT UNIQUE NOT NULL,display_name TEXT NOT NULL,bio TEXT DEFAULT '',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS creator_offerings(id INTEGER PRIMARY KEY AUTOINCREMENT,creator_id INTEGER NOT NULL,title TEXT NOT NULL,description TEXT DEFAULT '',price_minor INTEGER DEFAULT 0,currency TEXT DEFAULT 'ETB',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS creator_bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,offering_id INTEGER NOT NULL,buyer_user_id TEXT NOT NULL,status TEXT DEFAULT 'pending',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
app.post('/api/v97/creator/profile',auth,(req,res)=>{const name=String(req.body?.displayName||req.user.name||'Creator').slice(0,120),bio=String(req.body?.bio||'').slice(0,500);DB.prepare('INSERT INTO creator_profiles(user_id,display_name,bio) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name,bio=excluded.bio,active=1').run(req.user.id,name,bio);res.json({ok:true})});
app.post('/api/v97/creator/offerings',auth,(req,res)=>{const c=DB.prepare('SELECT * FROM creator_profiles WHERE user_id=? AND active=1').get(req.user.id);if(!c)return res.status(400).json({error:'Create creator profile first'});const title=String(req.body?.title||'Offering').slice(0,120);const desc=String(req.body?.description||'').slice(0,500);const price=Math.max(0,Math.round(Number(req.body?.priceMinor||0)));const currency=String(req.body?.currency||'ETB').slice(0,8);const r=DB.prepare('INSERT INTO creator_offerings(creator_id,title,description,price_minor,currency) VALUES(?,?,?,?,?)').run(c.id,title,desc,price,currency);res.json({ok:true,id:r.lastInsertRowid})});
app.get('/api/v97/marketplace',auth,(req,res)=>res.json({offerings:DB.prepare('SELECT o.*,c.display_name FROM creator_offerings o JOIN creator_profiles c ON c.id=o.creator_id WHERE o.active=1 AND c.active=1 ORDER BY o.created_at DESC LIMIT 100').all()}));
app.post('/api/v97/marketplace/:id/book',auth,(req,res)=>{const r=DB.prepare('INSERT INTO creator_bookings(offering_id,buyer_user_id) VALUES(?,?)').run(Number(req.params.id),req.user.id);res.json({ok:true,bookingId:r.lastInsertRowid,status:'pending'})});
app.get('/api/v97/features',(req,res)=>res.json({version:'97.0.0',features:{creatorProfiles:true,offerings:true,bookings:true,moderationReady:true}}));


// V98 Global Monetization foundation
DB.exec(`CREATE TABLE IF NOT EXISTS price_catalog(id INTEGER PRIMARY KEY AUTOINCREMENT,sku TEXT NOT NULL,country TEXT NOT NULL,currency TEXT NOT NULL,price_minor INTEGER NOT NULL,active INTEGER DEFAULT 1,UNIQUE(sku,country,currency)); CREATE TABLE IF NOT EXISTS entitlements(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,sku TEXT NOT NULL,status TEXT DEFAULT 'active',expires_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS transaction_ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,sku TEXT NOT NULL,currency TEXT NOT NULL,amount_minor INTEGER NOT NULL,status TEXT DEFAULT 'pending',provider TEXT DEFAULT 'unconfigured',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
app.get('/api/v98/catalog',auth,(req,res)=>{const country=String(req.query.country||'ET').slice(0,8);res.json({country,items:DB.prepare('SELECT sku,country,currency,price_minor,active FROM price_catalog WHERE country=? AND active=1 ORDER BY sku').all(country)})});
app.post('/api/v98/catalog',auth,admin,(req,res)=>{const sku=String(req.body?.sku||'').slice(0,80),country=String(req.body?.country||'ET').slice(0,8),currency=String(req.body?.currency||'ETB').slice(0,8),price=Math.max(0,Math.round(Number(req.body?.priceMinor||0)));if(!sku)return res.status(400).json({error:'SKU required'});DB.prepare('INSERT INTO price_catalog(sku,country,currency,price_minor) VALUES(?,?,?,?) ON CONFLICT(sku,country,currency) DO UPDATE SET price_minor=excluded.price_minor,active=1').run(sku,country,currency,price);res.json({ok:true})});
