// V99 Enterprise & Scale foundation
DB.exec(`CREATE TABLE IF NOT EXISTS organizations(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS organization_members(org_id INTEGER NOT NULL,user_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'member',created_at TEXT DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(org_id,user_id)); CREATE TABLE IF NOT EXISTS api_keys(id INTEGER PRIMARY KEY AUTOINCREMENT,org_id INTEGER NOT NULL,name TEXT NOT NULL,key_hash TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS audit_records(id INTEGER PRIMARY KEY AUTOINCREMENT,org_id INTEGER,user_id TEXT,event TEXT NOT NULL,metadata TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
app.post('/api/v99/orgs',auth,(req,res)=>{const name=String(req.body?.name||'').trim().slice(0,120);const slug=String(req.body?.slug||name.toLowerCase().replace(/[^a-z0-9]+/g,'-')).slice(0,80);if(!name||!slug)return res.status(400).json({error:'Name required'});try{const r=DB.prepare('INSERT INTO organizations(name,slug) VALUES(?,?)').run(name,slug);DB.prepare('INSERT INTO organization_members(org_id,user_id,role) VALUES(?,?,?)').run(r.lastInsertRowid,req.user.id,'owner');return res.json({ok:true,id:r.lastInsertRowid,slug})}catch(e){return res.status(409).json({error:'Organization slug already exists'})}});
app.get('/api/v99/orgs',auth,(req,res)=>res.json({organizations:DB.prepare('SELECT o.*,m.role FROM organizations o JOIN organization_members m ON m.org_id=o.id WHERE m.user_id=? ORDER BY o.id DESC').all(req.user.id)}));
app.post('/api/v99/orgs/:id/api-keys',auth,(req,res)=>{const org=DB.prepare('SELECT o.id FROM organizations o JOIN organization_members m ON m.org_id=o.id WHERE o.id=? AND m.user_id=? AND m.role IN (\'owner\',\'admin\')').get(Number(req.params.id),req.user.id);if(!org)return res.status(403).json({error:'Admin membership required'});const raw='hd_'+crypto.randomBytes(24).toString('hex');const hash=crypto.createHash('sha256').update(raw).digest('hex');const name=String(req.body?.name||'API key').slice(0,80);DB.prepare('INSERT INTO api_keys(org_id,name,key_hash) VALUES(?,?,?)').run(org.id,name,hash);res.json({ok:true,name,key:raw,warning:'Store this key securely; it will not be returned again.'})});
app.get('/api/v99/features',(req,res)=>res.json({version:'99.0.0',features:{organizations:true,roles:true,apiKeys:true,auditRecords:true,scaleReadiness:true}}));


