DB.exec(`CREATE TABLE IF NOT EXISTS currency_rates(id INTEGER PRIMARY KEY AUTOINCREMENT,base_currency TEXT NOT NULL,quote_currency TEXT NOT NULL,rate REAL NOT NULL,source TEXT DEFAULT 'manual',effective_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(base_currency,quote_currency)); CREATE TABLE IF NOT EXISTS payment_methods(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,country TEXT DEFAULT '',currency TEXT DEFAULT '',provider TEXT NOT NULL,provider_ref TEXT DEFAULT '',status TEXT DEFAULT 'active',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
