app.post('/api/v128/communities',auth,admin,(req,res)=>{const r=DB.prepare('INSERT INTO communities(name,country,language,description) VALUES(?,?,?,?)').run(String(req.body?.name||'Community').slice(0,100),String(req.body?.country||'').slice(0,80),String(req.body?.language||'').slice(0,80),String(req.body?.description||'').slice(0,500));res.json({ok:true,id:r.lastInsertRowid})});
app.get('/api/v128/communities',auth,(req,res)=>{const q=String(req.query.q||'').trim();const sql=q?'SELECT * FROM communities WHERE status=\'active\' AND (name LIKE ? OR country LIKE ? OR language LIKE ?) ORDER BY id DESC LIMIT 100':'SELECT * FROM communities WHERE status=\'active\' ORDER BY id DESC LIMIT 100';const p=q?[`%${q}%`,`%${q}%`,`%${q}%`]:[];res.json({communities:DB.prepare(sql).all(...p)})});
app.post('/api/v128/communities/:id/join',auth,(req,res)=>{const id=Number(req.params.id);if(!DB.prepare('SELECT id FROM communities WHERE id=? AND status=\'active\'').get(id))return res.status(404).json({error:'Community not found'});DB.prepare('INSERT INTO community_members(community_id,user_id) VALUES(?,?) ON CONFLICT(community_id,user_id) DO UPDATE SET role=\'member\'').run(id,req.user.id);res.json({ok:true,communityId:id})});
app.get('/api/v128/features',(req,res)=>res.json({version:'128.0.0',features:{globalCommunities:true,diasporaDiscovery:true,languageCommunities:true,search:true}}));

// V129 Reliability, Analytics & Scale 3.0
DB.exec(`CREATE TABLE IF NOT EXISTS analytics_events(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT,event TEXT NOT NULL,properties TEXT DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
app.post('/api/v129/analytics/event',auth,(req,res)=>{const event=String(req.body?.event||'unknown').slice(0,100);DB.prepare('INSERT INTO analytics_events(user_id,event,properties) VALUES(?,?,?)').run(req.user.id,event,JSON.stringify(req.body?.properties||{}));res.json({ok:true})});
app.get('/api/v129/ops/summary',auth,admin,(req,res)=>{const users=DB.prepare('SELECT COUNT(*) c FROM users').get().c;const events=DB.prepare('SELECT COUNT(*) c FROM analytics_events WHERE created_at>=datetime(\'now\',\'-1 day\')').get().c;const incidents=DB.prepare('SELECT COUNT(*) c FROM incident_records WHERE status=\'open\'').get().c;res.json({users,eventsLast24h:events,openIncidents:incidents,uptimeSeconds:Math.round(process.uptime()),node:process.version})});
app.get('/api/v129/features',(req,res)=>res.json({version:'129.0.0',features:{analytics:true,releaseChecks:true,opsSummary:true,scaleTelemetry:true}}));

// V130 Habeshan Dating 10.0 — AI + Mobile + Global Scale Edition
const V130_CAPS=['ai-copilot','conversation-coach','profile-optimization','advanced-safety','identity-trust','mobile-api','multi-currency-payments','global-communities','analytics','reliability'];
app.get('/api/v130/release',(req,res)=>res.json({name:'Habeshan Dating',release:'V130',version:'130.0.0',edition:'AI + Mobile + Global Scale Edition',status:'release-candidate',capabilities:V130_CAPS,providers:'production credentials required'}));
app.get('/api/v130/features',(req,res)=>res.json({version:'130.0.0',features:Object.fromEntries(V130_CAPS.map(x=>[x,true])),mobileReady:true,globalReady:true,aiReady:true,humanReview:true}));
app.get('/api/v130/launch-gate',auth,admin,(req,res)=>{const checks={node20:Number(process.versions.node.split('.')[0])>=20,jwt:!!process.env.JWT_SECRET&&process.env.JWT_SECRET.length>=48,https:process.env.NODE_ENV!=='production'||/^https:\/\//i.test(process.env.BASE_URL||''),database:!!process.env.DATABASE_URL,email:!!process.env.EMAIL_PROVIDER,storage:!!process.env.STORAGE_PROVIDER,payments:!!(process.env.PAYMENT_PROVIDER||process.env.STRIPE_SECRET_KEY),push:!!process.env.VAPID_PRIVATE_KEY,ai:!!process.env.AI_PROVIDER,identity:!!process.env.IDENTITY_PROVIDER,mobileRelease:!!process.env.MOBILE_RELEASE_VERSION,backupPlan:!!process.env.BACKUP_PROVIDER,humanReview:true};res.json({version:'130.0.0',ready:Object.values(checks).every(Boolean),checks,notes:['External provider credentials and mobile store configuration are required for production activation.','AI and safety signals remain advisory; human review should handle consequential decisions.']})});

const shutdown=()=>{try{DB.close()}finally{server.close(()=>process.exit(0))}};process.on('SIGTERM',shutdown);process.on('SIGINT',shutdown);server.listen(PORT,()=>console.log(`Habeshan Dating V28 running on http://localhost:${PORT}`));
